export const def = {
  name: 'brave_search_status',
  description: 'Is Brave Search connected? Pass check:true to confirm it answers with a real query.',
  input_schema: { type: 'object', properties: { check: { type: 'boolean' } }, required: [] },
};
export async function run(api, input) {
  const st = await api.gateway('brave', 'status', {});
  if (!st?.connected || !input?.check) return st;
  const p = await api.gateway('brave', 'probe', {});
  return { ...st, answering: !!p?.ok, error: p?.ok ? null : p?.error };
}

export const def = {
  name: 'connect_brave_search',
  description: 'Connect Brave Search as a web search provider (key from api.search.brave.com, free tier). The key is verified with a real query before it is stored.',
  input_schema: { type: 'object', properties: { api_key: { type: 'string' } }, required: ['api_key'] },
};
export async function run(api, input) {
  const key = String(input?.api_key || '').trim();
  if (!key) return { ok: false, error: 'no api_key given' };
  const v = await api.gateway('brave', 'verify', { api_key: key });
  if (!v?.ok) return { ok: false, error: `Brave rejected the key: ${v?.error || 'no answer'}` };
  await api.db.prepare(
    'INSERT INTO plugin_brave_search_config (id, api_key, updated_at) VALUES (1, ?, ?) ON CONFLICT(id) DO UPDATE SET api_key=excluded.api_key, updated_at=excluded.updated_at',
  ).bind(key, Date.now()).run();
  await api.log('connected', {});
  return { ok: true, note: 'Brave Search connected. The digest and search_web use it from now on.' };
}

export const def = {
  name: 'disconnect_brave_search',
  description: 'Forget the Brave Search key.',
  input_schema: { type: 'object', properties: {}, required: [] },
};
export async function run(api) {
  await api.db.prepare('DELETE FROM plugin_brave_search_config WHERE id = 1').run();
  await api.log('disconnected', {});
  return { ok: true, note: 'Brave Search forgotten.' };
}

export const def = {
  name: 'search_web',
  description: 'Search the web (Brave). Returns titles, links, and one-line summaries. Use when the operator asks to look something up, find a page, or check what exists on a topic beyond the news.',
  input_schema: {
    type: 'object',
    properties: { query: { type: 'string' }, limit: { type: 'number', description: 'default 5, cap 20' } },
    required: ['query'],
  },
};
export async function run(api, input) {
  const r = await api.gateway('brave', 'search', { query: input?.query, limit: input?.limit });
  if (!r?.ok) return { ok: false, error: r?.error || 'search failed' };
  await api.log('searched', { query: r.query, results: r.results.length });
  return { ok: true, query: r.query, results: r.results };
}

